import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'dart:convert';

void main() => runApp(const LoteriaApp());

class LoteriaApp extends StatelessWidget {
  const LoteriaApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner: false,
    title: 'Lotería Push',
    theme: ThemeData(colorScheme: ColorScheme.fromSeed(seedColor: const Color(0xffb3261e)), useMaterial3: true),
    home: const InicioPage(),
  );
}

class InicioPage extends StatefulWidget { const InicioPage({super.key}); @override State<InicioPage> createState()=>_InicioPageState(); }
class _InicioPageState extends State<InicioPage> {
  final nombre=TextEditingController(); final sala=TextEditingController(); final api=TextEditingController(text:'http://10.0.2.2:3000');
  bool cargando=false; String mensaje='Crea una sala como cantor o únete con un código.';
  Future<void> ejecutar(Future<void> Function() accion) async {setState(()=>cargando=true);try{await accion();}catch(e){if(mounted)setState(()=>mensaje=e.toString());}finally{if(mounted)setState(()=>cargando=false);}}
  Future<void> crear() async {final r=await http.post(Uri.parse('${api.text}/salas'));if(r.statusCode!=201)throw Exception('No se pudo crear sala');final d=jsonDecode(r.body);if(!mounted)return;Navigator.push(context,MaterialPageRoute(builder:(_)=>CantorPage(base:api.text,sala:d['sala'],clave:d['claveCantor'])));}
  Future<void> unir() async {final r=await http.post(Uri.parse('${api.text}/salas/${sala.text.trim().toUpperCase()}/unirse'),headers:{'content-type':'application/json'},body:jsonEncode({'nombre':nombre.text.trim()}));if(r.statusCode!=201)throw Exception(jsonDecode(r.body)['error']);final d=jsonDecode(r.body);if(!mounted)return;Navigator.push(context,MaterialPageRoute(builder:(_)=>JugadorPage(base:api.text,sala:sala.text.trim().toUpperCase(),nombre:d['nombre'],clave:d['claveJugador'],tabla:List<int>.from(d['tabla']))));}
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('🃏 Lotería Push')),body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(22),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:480),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Icon(Icons.casino,size:76,color:Color(0xffb3261e)),const SizedBox(height:12),Text('¡Que comience la lotería!',style:Theme.of(context).textTheme.headlineSmall,textAlign:TextAlign.center),const SizedBox(height:22),TextField(controller:api,decoration:const InputDecoration(labelText:'Dirección del servidor',prefixIcon:Icon(Icons.cloud))),const SizedBox(height:14),TextField(controller:nombre,decoration:const InputDecoration(labelText:'Tu nombre',prefixIcon:Icon(Icons.person))),const SizedBox(height:14),TextField(controller:sala,decoration:const InputDecoration(labelText:'Código de sala',prefixIcon:Icon(Icons.meeting_room))),const SizedBox(height:18),FilledButton.icon(onPressed:cargando?null:()=>ejecutar(unir),icon:const Icon(Icons.login),label:const Text('Unirme a una sala')),const SizedBox(height:10),OutlinedButton.icon(onPressed:cargando?null:()=>ejecutar(crear),icon:const Icon(Icons.campaign),label:const Text('Crear sala como cantor')),if(cargando)const Padding(padding:EdgeInsets.all(12),child:Center(child:CircularProgressIndicator())),const SizedBox(height:12),Text(mensaje,textAlign:TextAlign.center,style:Theme.of(context).textTheme.bodySmall)])))));
}

class CantorPage extends StatefulWidget {final String base,sala,clave;const CantorPage({super.key,required this.base,required this.sala,required this.clave});@override State<CantorPage> createState()=>_CantorPageState();}
class _CantorPageState extends State<CantorPage>{String actual='Todavía no hay cartas';bool busy=false;Future<void> cantar()async{setState(()=>busy=true);try{final r=await http.post(Uri.parse('${widget.base}/salas/${widget.sala}/cantar'),headers:{'x-clave-cantor':widget.clave});final d=jsonDecode(r.body);if(r.statusCode!=200)throw Exception(d['error']);setState(()=>actual='${d['carta']['nombre']}\n${d['carta']['pista']}');}catch(e){setState(()=>actual=e.toString());}finally{setState(()=>busy=false);}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text('Cantor · ${widget.sala}')),body:Center(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[const Text('Comparte este código con los jugadores'),SelectableText(widget.sala,style:Theme.of(context).textTheme.displayMedium),const SizedBox(height:30),Text(actual,textAlign:TextAlign.center,style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:28),FilledButton.icon(onPressed:busy?null:cantar,icon:const Icon(Icons.campaign),label:const Text('Cantar siguiente carta'))]))));}

class JugadorPage extends StatefulWidget{final String base,sala,nombre,clave;final List<int> tabla;const JugadorPage({super.key,required this.base,required this.sala,required this.nombre,required this.clave,required this.tabla});@override State<JugadorPage> createState()=>_JugadorPageState();}
class _JugadorPageState extends State<JugadorPage>{final Set<int> marcadas={};List<Map<String,dynamic>> cantadas=[];bool consultando=false;@override void initState(){super.initState();consultar();}Future<void> consultar()async{if(consultando)return;consultando=true;try{final r=await http.get(Uri.parse('${widget.base}/salas/${widget.sala}/estado?desde=0'));if(r.statusCode==200){final d=jsonDecode(r.body);setState(()=>cantadas=List<Map<String,dynamic>>.from(d['cartas']));}}catch(_){}finally{consultando=false;}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text('${widget.nombre} · ${widget.sala}'),actions:[IconButton(onPressed:consultar,icon:const Icon(Icons.refresh))]),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:Text('Toca las cartas que ya cantó el pregonero. Actualiza para consultar el servidor.',textAlign:TextAlign.center)),Expanded(child:GridView.builder(padding:const EdgeInsets.all(12),gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:4,crossAxisSpacing:8,mainAxisSpacing:8,childAspectRatio:.78),itemCount:16,itemBuilder:(context,i){final id=widget.tabla[i];final coincidencias=cantadas.where((x)=>x['id']==id).toList();final c=coincidencias.isEmpty?null:coincidencias.first;final activo=marcadas.contains(id);return InkWell(onTap:()=>setState(()=>activo?marcadas.remove(id):marcadas.add(id)),child:Container(decoration:BoxDecoration(color:activo?Colors.green.shade100:Theme.of(context).colorScheme.surfaceContainer,border:Border.all(color:c!=null?Colors.green:Colors.black26,width:c!=null?2:1),borderRadius:BorderRadius.circular(12)),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text('$id',style:const TextStyle(fontWeight:FontWeight.bold)),Padding(padding:const EdgeInsets.all(4),child:Text((c?['nombre'] as String?)??'Carta $id',textAlign:TextAlign.center,style:const TextStyle(fontSize:12))),if(c!=null)const Icon(Icons.check_circle,color:Colors.green,size:18)])));})),Padding(padding:const EdgeInsets.all(12),child:Text('Cartas cantadas: ${cantadas.length}'))]));}
